function splitTableRow(line) {
    const row = line.trim().replace(/^\|/, '').replace(/\|$/, '')
    return row.split('|').map((cell) => cell.trim())
}

function consumeTable(lines, start, ctx) {
    const headerCells = splitTableRow(lines[start])
    let index = start + 2
    const bodyRows = []

    while (index < lines.length && lines[index].includes('|') && lines[index].trim()) {
        bodyRows.push(splitTableRow(lines[index]))
        index += 1
    }

    const headerHtml = headerCells
        .map((cell) =>
            renderTag(
                'th',
                renderInline(cell, ctx),
                    {
                        padding: '12px 14px',
                        background: TOKENS.heroBackground,
                        color: '#f8fbff',
                    fontSize: '14px',
                    fontWeight: '700',
                    textAlign: 'left',
                    border: `1px solid #2b3138`
                    }
                )
        )
        .join('')

    const bodyHtml = bodyRows
        .map((row, rowIndex) =>
            `<tr>${row
                .map((cell) =>
                    renderTag(
                        'td',
                        renderInline(cell, ctx),
                        {
                            padding: '11px 14px',
                            border: `1px solid ${TOKENS.border}`,
                            fontSize: '14px',
                            lineHeight: '1.75',
                            color: TOKENS.foregroundSoft,
                            background: rowIndex % 2 === 0 ? '#ffffff' : TOKENS.backgroundSoft,
                            verticalAlign: 'top'
                        }
                    )
                )
                .join('')}</tr>`
        )
        .join('')

    return {
        next: index,
        html: `<section style="${styleString({
            margin: '22px 0',
            borderRadius: '8px',
            overflow: 'hidden'
        })}"><table style="${styleString({
            width: '100%',
            borderCollapse: 'collapse',
            background: '#ffffff'
        })}"><thead><tr>${headerHtml}</tr></thead><tbody>${bodyHtml}</tbody></table></section>`
    }
}

function consumeList(lines, start, ctx) {
    const ordered = /^\s*\d+\./.test(lines[start])
    const items = []
    let index = start

    while (index < lines.length) {
        const line = lines[index]
        const match = ordered ? line.match(/^\s*\d+\.\s+(.*)$/) : line.match(/^\s*[-+*]\s+(.*)$/)
        if (!match) break

        const fragments = [match[1]]
        index += 1

        while (index < lines.length && lines[index].trim() && !isBlockStart(lines, index)) {
            fragments.push(lines[index].trim())
            index += 1
        }

        const itemRaw = fragments.join(' ')
        const taskMatch = itemRaw.match(/^\[( |x|X)\]\s+(.*)$/)
        const itemNumber = items.length + 1
        const renderListRow = (marker, content, markerStyle = {}) =>
            `<section style="${styleString({
                display: 'table',
                width: '100%',
                margin: '8px 0',
                color: TOKENS.foreground,
                lineHeight: '1.85',
                borderCollapse: 'collapse'
            })}"><span style="${styleString({
                display: 'table-cell',
                width: '32px',
                minWidth: '32px',
                paddingRight: '8px',
                color: TOKENS.signalStrong,
                fontSize: '14px',
                fontWeight: '700',
                textAlign: 'center',
                verticalAlign: 'baseline',
                ...markerStyle
            })}">${marker}</span><span style="${styleString({
                display: 'table-cell',
                verticalAlign: 'baseline',
                color: TOKENS.foreground
            })}">${content}</span></section>`

        if (taskMatch && !ordered) {
            const checked = taskMatch[1].toLowerCase() === 'x'
            items.push(
                renderListRow(checked ? '✓' : '●', renderInline(taskMatch[2], ctx), {
                    fontSize: checked ? '14px' : '13px'
                })
            )
        } else {
            items.push(
                ordered
                    ? renderListRow(`${itemNumber}.`, renderInline(itemRaw, ctx), {
                          fontSize: '16px',
                          textAlign: 'center'
                      })
                    : renderListRow(
                          '●',
                          renderInline(itemRaw, ctx),
                          {
                              fontSize: '13px'
                          }
                      )
                )
        }

        while (index < lines.length && !lines[index].trim()) {
            index += 1
        }
    }

    return {
        next: index,
        html: `<section style="${styleString({
            margin: ordered ? '16px 0 18px' : '14px 0 18px',
            color: TOKENS.foreground
        })}">${items.join('')}</section>`
    }
}

function consumeParagraph(lines, start, ctx) {
    const fragments = []
    let index = start

    while (index < lines.length) {
        const line = lines[index]
        if (!line.trim()) break
        if (index !== start && isBlockStart(lines, index)) break
        fragments.push(line.trim())
        index += 1
    }

    const html = renderTag(
        'p',
        renderInline(fragments.join('\n'), ctx),
        {
            margin: '15px 0',
            color: TOKENS.foregroundSoft,
            fontSize: '16px',
            lineHeight: '1.88',
            textAlign: 'left'
        }
    )

    return { next: index, html }
}

function parseBlocks(lines, ctx) {
    const blocks = []

    for (let index = 0; index < lines.length; ) {
        const line = lines[index]

        if (!line || !line.trim()) {
            index += 1
            continue
        }

        if (isCodeFence(line)) {
            const result = consumeCodeBlock(lines, index)
            blocks.push(result.html)
            index = result.next
            continue
        }

        if (isTableStart(lines, index)) {
            const result = consumeTable(lines, index, ctx)
            blocks.push(result.html)
            index = result.next
            continue
        }

        if (isHeading(line)) {
            const result = consumeHeading(lines, index, ctx)
            blocks.push(result.html)
            index = result.next
            continue
        }

        if (isHr(line)) {
            const result = consumeHr(index)
            blocks.push(result.html)
            index = result.next
            continue
        }

        if (isBlockquote(line)) {
            const result = consumeBlockquote(lines, index, ctx)
            blocks.push(result.html)
            index = result.next
            continue
        }

        if (isListItem(line)) {
            const result = consumeList(lines, index, ctx)
            blocks.push(result.html)
            index = result.next
            continue
        }

        const result = consumeParagraph(lines, index, ctx)
        blocks.push(result.html)
        index = result.next
    }

    return blocks.join('')
}

function buildFootnotes(ctx) {
    if (!ctx.footnotes.length) return ''

    const items = ctx.footnotes
        .map(
            (item) =>
                `<section style="${styleString({
                    margin: '8px 0',
                    color: TOKENS.mutedForeground,
                    fontSize: '13px',
                    lineHeight: '1.8'
                })}"><span style="${styleString({
                    display: 'inline-block',
                    minWidth: '22px',
                    color: TOKENS.signalText,
                    fontWeight: '700'
                })}">[${item.index}]</span><span>${item.label ? `${escapeHtml(item.label)} - ` : ''}${escapeHtml(item.url)}</span></section>`
        )
        .join('')

    return `<section style="${styleString({
        marginTop: '34px',
        padding: '18px 18px 14px',
        borderRadius: '8px',
        backgroundColor: TOKENS.backgroundSoft,
        border: `1px solid ${TOKENS.borderStrong}`
    })}"><div style="${styleString({
        marginBottom: '10px',
        color: TOKENS.foreground,
        fontSize: '14px',
        fontWeight: '800',
        letterSpacing: '0'
    })}">参考链接</div><section style="${styleString({
        margin: '0',
        padding: '0'
    })}">${items}</section></section>`
}

function renderMarkdown(markdown) {
    const cleaned = stripFrontmatter(markdown).replace(/\r\n?/g, '\n')
    const lines = cleaned.split('\n')
    const ctx = createContext()
    const articleBody = parseBlocks(lines, ctx) + buildFootnotes(ctx)
    const titleMatch = cleaned.match(/^#\s+(.+)$/m)
    const title = titleMatch ? titleMatch[1].trim() : 'venom-gui-wechat-article'
    const articleHtml = `<section data-venom-wx="true" style="${styleString({
        boxSizing: 'border-box',
        width: '100%',
        padding: '0',
        backgroundColor: '#ffffff',
        color: TOKENS.foreground,
        fontFamily: TOKENS.fontSans,
        fontSize: '16px',
        lineHeight: '1.85'
    })}">${articleBody || renderTag(
        'p',
        '开始输入 Markdown，右侧会生成可粘贴到公众号编辑器的 HTML。',
        {
            margin: '0',
            color: TOKENS.mutedForeground,
            fontSize: '15px',
            lineHeight: '1.8'
        }
    )}</section>`

    return { html: articleHtml, title }
}

function calcStats(markdown) {
    const normalized = markdown.replace(/\r\n?/g, '\n')
    const chars = normalized.replace(/\s+/g, '').length
    const lines = normalized ? normalized.split('\n').length : 0
    const links = (normalized.match(/\[[^\]]+\]\(([^)]+)\)/g) || []).length + (normalized.match(/(?:https?:\/\/|www\.)[^\s)]+/g) || []).length
    const minutes = chars ? Math.max(1, Math.round(chars / 320)) : 0
    return { chars, lines, links, minutes }
}

function slugify(title) {
    return String(title || 'venom-gui-wechat-article')
        .trim()
        .replace(/[\\/:*?"<>|]/g, ' ')
        .replace(/\s+/g, '-')
        .replace(/-+/g, '-')
        .replace(/^-|-$/g, '')
        .slice(0, 80) || 'venom-gui-wechat-article'
}

function updateStats(markdown) {
    const stats = calcStats(markdown)
    refs.charCount.textContent = `字数 ${stats.chars}`
    refs.lineCount.textContent = `行数 ${stats.lines}`
    refs.linkCount.textContent = `链接 ${stats.links}`
    refs.readingTime.textContent = `阅读 ${stats.minutes} 分钟`
}

function setStatus(message, tone = '') {
    refs.renderStatus.textContent = message
    refs.renderStatus.className = 'status-text'
    if (tone) refs.renderStatus.classList.add(tone)
}

function renderAll() {
    const markdown = refs.markdownInput.value
    const result = renderMarkdown(markdown)
    state.renderedHtml = result.html
    state.renderedTitle = slugify(result.title)
    refs.wechatPreview.innerHTML = state.renderedHtml
    refs.htmlOutput.textContent = state.renderedHtml
    updateStats(markdown)
    localStorage.setItem(STORAGE_KEY, markdown)

    if (markdown.trim()) {
        setStatus('已完成实时转换，可直接复制到公众号编辑器。', 'success')
    } else {
        setStatus('等待输入 Markdown…')
    }
}

function switchView(view) {
    state.currentView = view
    document.querySelectorAll('[data-view]').forEach((button) => {
        button.classList.toggle('active', button.dataset.view === view)
    })
    refs.previewView.classList.toggle('active', view === 'preview')
    refs.sourceView.classList.toggle('active', view === 'source')
}

async function copyHtmlSource() {
    try {
        await navigator.clipboard.writeText(state.renderedHtml)
        setStatus('HTML 源码已复制。', 'success')
    } catch (_error) {
        setStatus('复制 HTML 失败，请检查浏览器剪贴板权限。', 'error')
    }
}

async function copyRichContent() {
    const plainText = refs.wechatPreview.innerText.trim()

    if (!window.ClipboardItem || !navigator.clipboard?.write) {
        await copyHtmlSource()
        setStatus('当前环境不支持富文本复制，已回退为复制 HTML 源码。', 'warn')
        return
    }

    try {
        const item = new ClipboardItem({
            'text/html': new Blob([state.renderedHtml], { type: 'text/html' }),
            'text/plain': new Blob([plainText], { type: 'text/plain' })
        })
        await navigator.clipboard.write([item])
        setStatus('公众号内容已复制，可以直接粘贴到微信编辑器。', 'success')
    } catch (_error) {
        await copyHtmlSource()
        setStatus('富文本复制失败，已回退为复制 HTML 源码。建议在 localhost 或 https 环境下使用。', 'warn')
    }
}

function downloadHtmlDocument() {
    const title = state.renderedTitle || 'venom-gui-wechat-article'
    const documentHtml = `<!doctype html>
<html lang="zh-CN">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>${escapeHtml(title)}</title>
</head>
<body style="margin:0;padding:40px;background:#f4f6f8;font-family:${TOKENS.fontSans};">
    <main style="max-width:860px;margin:0 auto;padding:4px;">
        ${state.renderedHtml}
    </main>
</body>
</html>`

    const blob = new Blob([documentHtml], { type: 'text/html;charset=utf-8' })
    const url = URL.createObjectURL(blob)
    const anchor = document.createElement('a')
    anchor.href = url
    anchor.download = `${title}.html`
    document.body.appendChild(anchor)
    anchor.click()
    anchor.remove()
    URL.revokeObjectURL(url)
    setStatus('HTML 文件已下载。', 'success')
}

async function importMarkdownFile(event) {
    const files = Array.from(event.target.files || [])
    if (!files.length) return

    try {
        const markdownFile = files.find(isMarkdownFile)
        const imageFiles = files.filter(isImageFile)

        await Promise.all(
            imageFiles.map(async (file) => {
                rememberImageData(file, await fileToDataUri(file))
            })
        )

        if (markdownFile) {
            refs.markdownInput.value = await markdownFile.text()
        }

        renderAll()
        const parts = []
        if (markdownFile) parts.push(markdownFile.name)
        if (imageFiles.length) parts.push(`${imageFiles.length} 张图片已转为 base64`)
        setStatus(`已导入 ${parts.join('，')}。`, 'success')
    } catch (_error) {
        setStatus('导入 Markdown 或图片失败，请重试。', 'error')
    } finally {
        event.target.value = ''
    }
}

function insertAtCursor(text) {
    const input = refs.markdownInput
    const start = input.selectionStart ?? input.value.length
    const end = input.selectionEnd ?? start
    input.value = `${input.value.slice(0, start)}${text}${input.value.slice(end)}`
    input.focus()
    input.selectionStart = start + text.length
    input.selectionEnd = start + text.length
    renderAll()
}

async function pasteImageFiles(event) {
    const files = Array.from(event.clipboardData?.files || []).filter(isImageFile)
    if (!files.length) return

    event.preventDefault()

    try {
        const snippets = await Promise.all(
            files.map(async (file) => {
                const dataUri = await fileToDataUri(file)
                rememberImageData(file, dataUri)
                const alt = file.name.replace(/\.[^.]+$/, '') || 'image'
                return `![${alt}](${dataUri})`
            })
        )
        insertAtCursor(`\n${snippets.join('\n\n')}\n`)
        setStatus(`${files.length} 张图片已转成 base64 并插入。`, 'success')
    } catch (_error) {
        setStatus('粘贴图片失败，请重试。', 'error')
    }
}

function insertSample() {
    refs.markdownInput.value = SAMPLE_MARKDOWN
    renderAll()
    setStatus('示例内容已填充。', 'success')
}

function clearMarkdown() {
    refs.markdownInput.value = ''
    renderAll()
    setStatus('内容已清空。')
}

function bindEvents() {
    refs.markdownInput.addEventListener('input', renderAll)
    refs.markdownInput.addEventListener('paste', pasteImageFiles)
    document.getElementById('sampleBtn').addEventListener('click', insertSample)
    document.getElementById('clearBtn').addEventListener('click', clearMarkdown)
    document.getElementById('importBtn').addEventListener('click', () => refs.fileInput.click())
    document.getElementById('copyHtmlBtn').addEventListener('click', copyHtmlSource)
    document.getElementById('copyRichBtn').addEventListener('click', copyRichContent)
    document.getElementById('downloadBtn').addEventListener('click', downloadHtmlDocument)
    refs.fileInput.addEventListener('change', importMarkdownFile)

    document.querySelectorAll('[data-view]').forEach((button) => {
        button.addEventListener('click', () => switchView(button.dataset.view))
    })
}

function bootstrap() {
    const stored = localStorage.getItem(STORAGE_KEY)
    refs.markdownInput.value = stored && stored.trim() ? stored : SAMPLE_MARKDOWN
    bindEvents()
    switchView('preview')
    renderAll()
}

bootstrap()
